package com.estoqueinteligente.config;
import org.springframework.context.annotation.*;import org.springframework.security.authentication.*;import org.springframework.security.authentication.dao.DaoAuthenticationProvider;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import com.estoqueinteligente.auth.*;
@Configuration public class SecurityConfig{@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}@Bean DaoAuthenticationProvider authenticationProvider(CustomUserDetailsService users,PasswordEncoder encoder){DaoAuthenticationProvider provider=new DaoAuthenticationProvider(users);provider.setPasswordEncoder(encoder);return provider;}@Bean AuthenticationManager authenticationManager(AuthenticationConfiguration configuration)throws Exception{return configuration.getAuthenticationManager();}@Bean SecurityFilterChain securityFilterChain(HttpSecurity http,JwtAuthenticationFilter jwt,RestAuthenticationEntryPoint entryPoint,DaoAuthenticationProvider provider)throws Exception{return http.csrf(csrf->csrf.disable()).cors(cors->{}).sessionManagement(session->session.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(errors->errors.authenticationEntryPoint(entryPoint)).authenticationProvider(provider).authorizeHttpRequests(auth->auth.requestMatchers("/health").permitAll().requestMatchers(org.springframework.http.HttpMethod.POST,"/auth/login").permitAll().requestMatchers(org.springframework.http.HttpMethod.POST,"/auth/register").hasRole("ADMIN").anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}}
